with flattened as (select id, plan, effective_from, currency, tier_value from price_tiers lateral view outer explode(tier_prices) x as tier_value) select id, plan, effective_from, percent_rank() over (partition by plan order by tier_value desc nulls last) as tier_value_percent_rank, count(tier_value) over (partition by plan) as plan_count_tier_value, cume_dist() over (partition by plan, currency order by tier_value nulls first) as tier_value_cume_dist from flattened where currency != 'THB';
